import type { Metadata } from 'next';
import { SkipLink } from '@/components/skip-link';
import { SiteHeader } from '@/components/site-header';
import { apfelGrotezk, commitMono } from '@/lib/fonts';
import { SITE_CONFIG } from '@/lib/constants';
import './globals.css';

/**
 * `metadataBase` is what turns every relative metadata path below and in
 * the pages (canonicals, Open Graph images generated by file conventions)
 * into an absolute URL. Without it Next falls back to the deployment URL,
 * which on Vercel means preview deployments would advertise themselves as
 * canonical. The value is the www origin, since the apex 308-redirects to
 * it, so canonicals must point at the redirect target, not its source.
 */
export const metadata: Metadata = {
  metadataBase: new URL(SITE_CONFIG.siteUrl),
  /**
   * `template` appends the brand suffix to every child segment's title, so
   * pages declare only their own subject and never repeat the name by hand.
   * It applies to child segments only, never to this one, which is why the
   * homepage title lives in `default` and keeps its full standalone form.
   * The template covers `<title>` only: Next does not apply it to
   * `openGraph.title` or `twitter.title`, so child segments still spell the
   * suffix out in their social blocks. That is the wanted behaviour anyway,
   * since a shared card carries no site chrome to supply the brand.
   */
  title: {
    default: 'Tristan Hourtoulle · Design et développement web freelance',
    template: '%s · Tristan Hourtoulle',
  },
  /**
   * Kept inside the ~155 character budget Google renders before it
   * truncates a French snippet. The previous value ran to 182 and lost
   * its closing clause ("de la maquette Figma à la mise en ligne"),
   * which is the differentiator the whole line exists to deliver. This
   * one is 151 and keeps every term a prospect actually types: the two
   * trades, the two deliverables, the three audiences, and both ends of
   * the process.
   */
  description:
    'Développeur web full-stack et designer freelance. Sites vitrines et applications sur mesure pour PME, startups et agences, de Figma à la mise en ligne.',
  openGraph: {
    title: 'Tristan Hourtoulle · Design et développement web freelance',
    description:
      "Développeur web full-stack et designer freelance. Un seul interlocuteur du premier appel à la mise en ligne.",
    type: 'website',
    locale: 'fr_FR',
    siteName: SITE_CONFIG.brandName,
    url: '/',
  },
  /**
   * No `creator` handle: there is no X/Twitter account for this business,
   * and inventing one would point the card at someone else. The image is
   * left unset on purpose too, so the `opengraph-image` file convention
   * can supply it automatically once it exists.
   */
  twitter: {
    card: 'summary_large_image',
    title: 'Tristan Hourtoulle · Design et développement web freelance',
    description:
      "Développeur web full-stack et designer freelance. Un seul interlocuteur du premier appel à la mise en ligne.",
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="fr" className={`${apfelGrotezk.variable} ${commitMono.variable}`}>
      <body className="antialiased">
        <SkipLink />
        <SiteHeader />
        {children}
      </body>
    </html>
  );
}
